WITH scored AS (SELECT *, MIN(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_budget, SUM(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_budget, MAX(budget) OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_budget FROM departments) SELECT dept_name, CASE WHEN running_min_budget >= 3832000 THEN 'LARGE' ELSE 'SMALL' END AS running_min_budget_tier, SUM(running_sum_budget) FILTER (WHERE dept_name = 'Engineering') AS engineering_total_running_sum_budget, COUNT(CASE WHEN dept_name = 'Marketing' THEN 1 END) AS marketing_count FROM scored GROUP BY dept_name, CASE WHEN running_min_budget >= 3832000 THEN 'LARGE' ELSE 'SMALL' END;
